CREATE OR REPLACE TABLE scratch.s2 AS SELECT l.purpose, COUNT(*) AS loans, ROUND(SUM(m.closing_balance),0) AS balance FROM loan_monthly_snapshot m JOIN loan l USING (loan_id) JOIN property p ON p.property_id=l.property_id JOIN dim_postcode d ON d.postcode=p.postcode WHERE m.snapshot_date=DATE '2025-12-31' AND m.loan_status<>'Closed' AND d.state='QLD' GROUP BY 1; SELECT purpose, loans, balance FROM scratch.s2 ORDER BY 1
